import math
import torch
import torch.nn as nn
from torch.nn import init
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.extern .shared .align 16 .b8 smem[];
.visible .entry conv_transpose3d_kernel(
    .param .u64 x_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 y_ptr,
    .param .u32 N,
    .param .u32 C_in,
    .param .u32 C_out,
    .param .u32 D_in,
    .param .u32 H_in,
    .param .u32 W_in,
    .param .u32 D_out,
    .param .u32 H_out,
    .param .u32 W_out,
    .param .u32 K,
    .param .u32 stride,
    .param .u32 padding,
    .param .u32 groups,
    .param .u32 has_bias
)
{
    // Registers
    .reg .pred  p_tmp, p_active, p_hasBias;
    .reg .b32   rN, rCin, rCout, rDin, rHin, rWin, rDout, rHout, rWout;
    .reg .b32   rK, rS, rP, rG, rHasBias;
    .reg .b32   r_tid, r_bdim, r_bidx, r_wi;
    .reg .b32   r_ho, r_z, r_totalCD, r_totalAll;
    .reg .b32   r_n, r_co, r_do, r_tmp32, r_rem, r_cpg, r_cig;
    .reg .b32   r_grp, r_co_g, r_in_cg, r_ci;
    .reg .b32   r_kd, r_kh, r_kw;
    .reg .s32   t_d_num, t_h_num, t_w_num, t_div, t_rem;
    .reg .b32   r_di, r_hi, r_wii;
    .reg .b32   r_idx, r_tmpA, r_tmpB, r_tmpC, r_tmpD;
    .reg .b32   rK2, rK3, rWN, r_t;
    .reg .b64   px, pw, pb, py;
    .reg .b64   addr, off, smem_ptr;
    .reg .f32   f_sum, f_x, f_w, f_b;
    // Load params
    ld.param.u64 px, [x_ptr];
    ld.param.u64 pw, [w_ptr];
    ld.param.u64 pb, [b_ptr];
    ld.param.u64 py, [y_ptr];
    ld.param.u32 rN, [N];
    ld.param.u32 rCin, [C_in];
    ld.param.u32 rCout, [C_out];
    ld.param.u32 rDin, [D_in];
    ld.param.u32 rHin, [H_in];
    ld.param.u32 rWin, [W_in];
    ld.param.u32 rDout, [D_out];
    ld.param.u32 rHout, [H_out];
    ld.param.u32 rWout, [W_out];
    ld.param.u32 rK, [K];
    ld.param.u32 rS, [stride];
    ld.param.u32 rP, [padding];
    ld.param.u32 rG, [groups];
    ld.param.u32 rHasBias, [has_bias];
    // Thread/block indices
    mov.u32 r_tid, %tid.x;
    mov.u32 r_bdim, %ntid.x;
    mov.u32 r_bidx, %ctaid.x;
    mad.lo.s32 r_wi, r_bidx, r_bdim, r_tid; // width index
    mov.u32 r_ho, %ctaid.y;                 // height index
    mov.u32 r_z, %ctaid.z;                  // packed (n,co,do)
    // Compute totalCD and totalAll (for decode only)
    mul.lo.u32 r_totalCD, rCout, rDout;
    mul.lo.u32 r_totalAll, rN, r_totalCD;
    // Decode n, co, do from z
    div.u32 r_n, r_z, r_totalCD;
    mul.lo.u32 r_tmp32, r_n, r_totalCD;
    sub.s32 r_rem, r_z, r_tmp32;
    div.u32 r_co, r_rem, rDout;
    mul.lo.u32 r_tmp32, r_co, rDout;
    sub.s32 r_do, r_rem, r_tmp32;
    // Group/channel partitioning
    div.u32 r_cpg, rCout, rG;    // channels per group (out)
    div.u32 r_cig, rCin, rG;     // channels per group (in)
    div.u32 r_grp, r_co, r_cpg;  // group index
    mul.lo.u32 r_tmp32, r_grp, r_cpg;
    sub.s32 r_co_g, r_co, r_tmp32; // co within group
    // Precompute K^2 and K^3 and total weights to stage
    mul.lo.u32 rK2, rK, rK;
    mul.lo.u32 rK3, rK2, rK;
    mul.lo.u32 rWN, r_cig, rK3; // number of weights to stage for this (co_g)
    // Get base shared memory pointer
     mov.u64 smem_ptr, smem;
    // Cooperative stage of weights w[ci, co_g, kd, kh, kw] for all ci in group into shared memory
    mov.u32 r_t, r_tid;
L_STAGE:
    setp.ge.u32 p_tmp, r_t, rWN;
    @p_tmp bra L_STAGE_END;
        // Decompose linear index r_t into (ci_g, kd, kh, kw)
        div.u32 r_tmpA, r_t, rK3;          // r_tmpA = ci_g
        mul.lo.u32 r_tmpB, r_tmpA, rK3;    // r_tmpB = ci_g*K^3
        sub.s32 r_tmpC, r_t, r_tmpB;       // r_tmpC = rem0
        div.u32 r_kd, r_tmpC, rK2;
        mul.lo.u32 r_tmpB, r_kd, rK2;
        sub.s32 r_tmpD, r_tmpC, r_tmpB;    // r_tmpD = rem1
        div.u32 r_kh, r_tmpD, rK;
        mul.lo.u32 r_tmpB, r_kh, rK;
        sub.s32 r_kw, r_tmpD, r_tmpB;
        // ci = grp*cig + ci_g
        mul.lo.u32 r_tmpB, r_grp, r_cig;
        add.u32    r_ci,  r_tmpB, r_tmpA;
        // Global w index: (((((ci*cpg + co_g)*K + kd)*K + kh)*K) + kw)
        mul.lo.u32 r_tmpB, r_ci, r_cpg;
        add.u32    r_tmpB, r_tmpB, r_co_g;
        mul.lo.u32 r_tmpB, r_tmpB, rK;
        add.u32    r_tmpB, r_tmpB, r_kd;
        mul.lo.u32 r_tmpB, r_tmpB, rK;
        add.u32    r_tmpB, r_tmpB, r_kh;
        mul.lo.u32 r_tmpB, r_tmpB, rK;
        add.u32    r_tmpB, r_tmpB, r_kw;
        mul.wide.u32 off, r_tmpB, 4;
        add.s64 addr, pw, off;
        ld.global.f32 f_w, [addr];
        // Store to shared memory at offset r_t
        mul.wide.u32 off, r_t, 4;
        add.s64 addr, smem_ptr, off;
        st.shared.f32 [addr], f_w;
        // Next
        add.u32 r_t, r_t, r_bdim;
        bra L_STAGE;
L_STAGE_END:
    // Ensure all weights are staged
    bar.sync 0;
    // Active thread predicate (width tail handling)
    setp.lt.u32 p_active, r_wi, rWout;
    // Initialize accumulator with bias (if any) for active threads
    mov.f32 f_sum, 0f00000000;
    @!p_active bra SKIP_BIAS;
        setp.ne.u32 p_hasBias, rHasBias, 0;
        @!p_hasBias bra SKIP_BIAS;
            mul.wide.u32 off, r_co, 4;
            add.s64 addr, pb, off;
            ld.global.f32 f_b, [addr];
            mov.f32 f_sum, f_b;
    SKIP_BIAS:
    // Skip compute for inactive threads
    @!p_active bra SKIP_COMPUTE;
    // Loop over input channels within group
    mov.u32 r_in_cg, 0;
L_IN_CG:
    setp.ge.u32 p_tmp, r_in_cg, r_cig;
    @p_tmp bra L_END_IN_CG;
        // ci = grp*cig + in_cg
        mul.lo.u32 r_tmp32, r_grp, r_cig;
        add.u32 r_ci, r_tmp32, r_in_cg;
        // kd loop
        mov.u32 r_kd, 0;
    L_KD:
        setp.ge.u32 p_tmp, r_kd, rK;
        @p_tmp bra L_END_KD;
            // t_d_num = do + padding - kd
            add.s32 t_d_num, r_do, rP;
            sub.s32 t_d_num, t_d_num, r_kd;
            // if t_d_num < 0 continue
            setp.lt.s32 p_tmp, t_d_num, 0;
            @p_tmp bra L_NEXT_KD;
            // if t_d_num % stride != 0 continue
            rem.s32 t_rem, t_d_num, rS;
            setp.ne.s32 p_tmp, t_rem, 0;
            @p_tmp bra L_NEXT_KD;
            // di = t_d_num / stride
            div.s32 t_div, t_d_num, rS;
            mov.u32 r_di, t_div;
            // if di >= D_in continue
            setp.ge.u32 p_tmp, r_di, rDin;
            @p_tmp bra L_NEXT_KD;
            // kh loop
            mov.u32 r_kh, 0;
        L_KH:
            setp.ge.u32 p_tmp, r_kh, rK;
            @p_tmp bra L_END_KH;
                // t_h_num = ho + padding - kh
                add.s32 t_h_num, r_ho, rP;
                sub.s32 t_h_num, t_h_num, r_kh;
                setp.lt.s32 p_tmp, t_h_num, 0;
                @p_tmp bra L_NEXT_KH;
                rem.s32 t_rem, t_h_num, rS;
                setp.ne.s32 p_tmp, t_rem, 0;
                @p_tmp bra L_NEXT_KH;
                div.s32 t_div, t_h_num, rS;
                mov.u32 r_hi, t_div;
                setp.ge.u32 p_tmp, r_hi, rHin;
                @p_tmp bra L_NEXT_KH;
                // kw loop
                mov.u32 r_kw, 0;
            L_KW:
                setp.ge.u32 p_tmp, r_kw, rK;
                @p_tmp bra L_END_KW;
                    // t_w_num = wi + padding - kw
                    add.s32 t_w_num, r_wi, rP;
                    sub.s32 t_w_num, t_w_num, r_kw;
                    setp.lt.s32 p_tmp, t_w_num, 0;
                    @p_tmp bra L_NEXT_KW;
                    rem.s32 t_rem, t_w_num, rS;
                    setp.ne.s32 p_tmp, t_rem, 0;
                    @p_tmp bra L_NEXT_KW;
                    div.s32 t_div, t_w_num, rS;
                    mov.u32 r_wii, t_div;
                    setp.ge.u32 p_tmp, r_wii, rWin;
                    @p_tmp bra L_NEXT_KW;
                    // Load x[n, ci, di, hi, wi]
                    // r_idx = (((((n*Cin + ci)*Din + di)*Hin + hi)*Win) + wi)
                    mul.lo.u32 r_tmpA, r_n, rCin;
                    add.u32    r_tmpA, r_tmpA, r_ci;
                    mul.lo.u32 r_tmpA, r_tmpA, rDin;
                    add.u32    r_tmpA, r_tmpA, r_di;
                    mul.lo.u32 r_tmpA, r_tmpA, rHin;
                    add.u32    r_tmpA, r_tmpA, r_hi;
                    mul.lo.u32 r_tmpA, r_tmpA, rWin;
                    add.u32    r_idx, r_tmpA, r_wii;
                    mul.wide.u32 off, r_idx, 4;
                    add.s64 addr, px, off;
                    ld.global.f32 f_x, [addr];
                    // Load staged w from shared memory: idx = in_cg*K^3 + kd*K^2 + kh*K + kw
                    mul.lo.u32 r_tmpB, r_in_cg, rK3;
                    mul.lo.u32 r_tmpC, r_kd, rK2;
                    add.u32    r_tmpB, r_tmpB, r_tmpC;
                    mul.lo.u32 r_tmpC, r_kh, rK;
                    add.u32    r_tmpB, r_tmpB, r_tmpC;
                    add.u32    r_tmpB, r_tmpB, r_kw;
                    mul.wide.u32 off, r_tmpB, 4;
                    add.s64 addr, smem_ptr, off;
                    ld.shared.f32 f_w, [addr];
                    // sum += x * w
                    fma.rn.f32 f_sum, f_x, f_w, f_sum;
                L_NEXT_KW:
                    add.u32 r_kw, r_kw, 1;
                    bra L_KW;
            L_END_KW:
            L_NEXT_KH:
                add.u32 r_kh, r_kh, 1;
                bra L_KH;
        L_END_KH:
        L_NEXT_KD:
            add.u32 r_kd, r_kd, 1;
            bra L_KD;
    L_END_KD:
        add.u32 r_in_cg, r_in_cg, 1;
        bra L_IN_CG;
L_END_IN_CG:
SKIP_COMPUTE:
    // Store y[n, co, do, ho, wo] for active threads
    @!p_active bra RET;
        // oidx = (((((n*Cout + co)*Dout + do)*Hout + ho)*Wout) + wo)
        mul.lo.u32 r_tmpC, r_n, rCout;
        add.u32    r_tmpC, r_tmpC, r_co;
        mul.lo.u32 r_tmpC, r_tmpC, rDout;
        add.u32    r_tmpC, r_tmpC, r_do;
        mul.lo.u32 r_tmpC, r_tmpC, rHout;
        add.u32    r_tmpC, r_tmpC, r_ho;
        mul.lo.u32 r_tmpC, r_tmpC, rWout;
        add.u32    r_tmpC, r_tmpC, r_wi;
        mul.wide.u32 off, r_tmpC, 4;
        add.s64 addr, py, off;
        st.global.f32 [addr], f_sum;
RET:
    ret;
}
"""
_ptx_module = None
def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module
def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv_transpose3d_kernel")
class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0, groups: int = 1, bias: bool = False):
        super().__init__()
        assert isinstance(kernel_size, int), "Only cubic kernels supported"
        assert isinstance(stride, int) and isinstance(padding, int) and isinstance(output_padding, int), "Only int stride/padding/output_padding supported"
        assert groups >= 1 and in_channels % groups == 0 and out_channels % groups == 0, "Invalid groups"
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups
        weight_shape = (in_channels, out_channels // groups, kernel_size, kernel_size, kernel_size)
        self.weight = nn.Parameter(torch.empty(weight_shape))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.bias = None
        self.reset_parameters()
    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in)
            init.uniform_(self.bias, -bound, bound)
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be on CUDA device"
        assert x.dtype == torch.float32, "Only float32 supported"
        assert x.dim() == 5, "Input must be NCDHW"
        N, Cin, Din, Hin, Win = x.shape
        assert Cin == self.in_channels, "Channel mismatch"
        K = self.kernel_size
        S = self.stride
        P = self.padding
        OP = self.output_padding
        G = self.groups
        Cout = self.out_channels
        # Output sizes according to ConvTranspose3d (dilation=1)
        Dout = (Din - 1) * S - 2 * P + (K - 1) + OP + 1
        Hout = (Hin - 1) * S - 2 * P + (K - 1) + OP + 1
        Wout = (Win - 1) * S - 2 * P + (K - 1) + OP + 1
        # Allocate output
        y = torch.empty((N, Cout, Dout, Hout, Wout), device=x.device, dtype=x.dtype)
        # Launch kernel
        module = _get_ptx_module()
        block_x = 128
        grid_x = (Wout + block_x - 1) // block_x
        grid_y = Hout
        grid_z = N * Cout * Dout
        has_bias = 1 if self.bias is not None else 0
        b_ptr_arg = self.bias if self.bias is not None else u64(0)
        # Dynamic shared memory for staged weights: (Cin/groups) * K^3 * sizeof(float)
        cig = Cin // G
        shared_memory = int(cig * (K * K * K) * 4)
        module.launch(
            "conv_transpose3d_kernel",
            grid=(int(grid_x), int(grid_y), int(grid_z)),
            block=(int(block_x), 1, 1),
            arguments=[
                x,                             # x_ptr
                self.weight,                   # w_ptr
                b_ptr_arg,                     # b_ptr or 0
                y,                             # y_ptr
                i32(N),
                i32(Cin),
                i32(Cout),
                i32(Din),
                i32(Hin),
                i32(Win),
                i32(Dout),
                i32(Hout),
                i32(Wout),
                i32(K),
                i32(S),
                i32(P),
                i32(G),
                u32(has_bias),
            ],
            shared_memory=int(shared_memory),
            stream=torch.cuda.current_stream(x.device),
        )
        return y

